-- JOB DB5: member_status_history policies current_unit_id() -> public.my_unit() (strict: blank lodge = no access).
-- Type (PERMISSIVE), command, roles and role tests unchanged; ALTER POLICY keeps them.
-- ORIGINAL: "Admin Secretary WM read status history" PERMISSIVE SELECT TO authenticated USING ((unit_id = current_unit_id()) AND (has_role(auth.uid(), 'admin'::app_role) OR is_lodge_secretary(auth.uid()) OR has_role(auth.uid(), 'worshipful_master'::app_role) OR is_current_officer(auth.uid(), 'worshipful_master'::text)))
ALTER POLICY "Admin Secretary WM read status history" ON public.member_status_history USING ((unit_id = public.my_unit()) AND (has_role(auth.uid(), 'admin'::app_role) OR is_lodge_secretary(auth.uid()) OR has_role(auth.uid(), 'worshipful_master'::app_role) OR is_current_officer(auth.uid(), 'worshipful_master'::text)));
-- ORIGINAL: "Admin or Secretary delete status history" PERMISSIVE DELETE TO authenticated USING ((unit_id = current_unit_id()) AND (has_role(auth.uid(), 'admin'::app_role) OR is_lodge_secretary(auth.uid())))
ALTER POLICY "Admin or Secretary delete status history" ON public.member_status_history USING ((unit_id = public.my_unit()) AND (has_role(auth.uid(), 'admin'::app_role) OR is_lodge_secretary(auth.uid())));
-- ORIGINAL: "Admin or Secretary update status history" PERMISSIVE UPDATE TO authenticated USING ((unit_id = current_unit_id()) AND (has_role(auth.uid(), 'admin'::app_role) OR is_lodge_secretary(auth.uid()))) WITH CHECK ((unit_id = current_unit_id()) AND (has_role(auth.uid(), 'admin'::app_role) OR is_lodge_secretary(auth.uid())))
ALTER POLICY "Admin or Secretary update status history" ON public.member_status_history USING ((unit_id = public.my_unit()) AND (has_role(auth.uid(), 'admin'::app_role) OR is_lodge_secretary(auth.uid()))) WITH CHECK ((unit_id = public.my_unit()) AND (has_role(auth.uid(), 'admin'::app_role) OR is_lodge_secretary(auth.uid())));
-- ORIGINAL: "Admin or Secretary write status history" PERMISSIVE INSERT TO authenticated WITH CHECK ((unit_id = current_unit_id()) AND (has_role(auth.uid(), 'admin'::app_role) OR is_lodge_secretary(auth.uid())))
ALTER POLICY "Admin or Secretary write status history" ON public.member_status_history WITH CHECK ((unit_id = public.my_unit()) AND (has_role(auth.uid(), 'admin'::app_role) OR is_lodge_secretary(auth.uid())));